cat > /tmp/analyze_gsm8k_2.py << 'PYEOF'
import json, os

# Check what model was actually evaluated - look at directory structure
base = '/root/autodl-tmp/exp001/'
print("=== SFT checkpoints ===")
for d in ['Qwen2.5-3B_d000_s42_v3', 'Qwen2.5-3B_d000_v2_s123']:
    path = os.path.join(base, d)
    if os.path.exists(path):
        print(f'{d}: exists')
        contents = os.listdir(path)
        print(f'  contents: {contents[:10]}')
    else:
        print(f'{d}: NOT FOUND')

# Check for eval config
for suffix in ['_aligned']:
    for d in ['Qwen2.5-3B_d000_s42_v3', 'Qwen2.5-3B_d000_v2_s123']:
        evaldir = os.path.join(base, 'eval_results', d + suffix)
        if os.path.exists(evaldir):
            files = os.listdir(evaldir)
            print(f'\n{d}{suffix} files: {files}')

# Look for eval logs
logdirs = []
for root, dirs, files in os.walk(os.path.join(base, 'eval_results')):
    for f in files:
        if 'log' in f.lower() or 'config' in f.lower():
            logdirs.append(os.path.join(root, f))
    break
print(f'\nLog/config files in eval_results: {logdirs}')

# Check if the eval script or config is stored somewhere
for f in ['eval_config.json', 'eval_config.yaml', 'config.json']:
    for d in ['Qwen2.5-3B_d000_s42_v3_aligned', 'Qwen2.5-3B_d000_v2_s123_aligned']:
        p = os.path.join(base, 'eval_results', d, f)
        if os.path.exists(p):
            print(f'\nFound: {p}')
            print(json.load(open(p)))

# Deeper answer analysis
ir42 = {x['item_id']: x for x in json.load(open(os.path.join(base, 'eval_results/Qwen2.5-3B_d000_s42_v3_aligned/item_responses.json'))) if x['benchmark']=='gsm8k'}
ir123 = {x['item_id']: x for x in json.load(open(os.path.join(base, 'eval_results/Qwen2.5-3B_d000_v2_s123_aligned/item_responses.json'))) if x['benchmark']=='gsm8k'}

# Check if answers are identical when both correct
both_correct_same = 0
both_correct_diff = 0
for iid in ir42:
    if ir42[iid]['correct'] and ir123[iid]['correct']:
        if ir42[iid]['model_answer'] == ir123[iid]['model_answer']:
            both_correct_same += 1
        else:
            both_correct_diff += 1

print(f'\nBoth correct, same answer: {both_correct_same}')
print(f'Both correct, diff answer: {both_correct_diff}')

# Format issues - check "26" vs "26.00" type
format_issues = 0
for iid in ir42:
    a42, a123 = ir42[iid]['model_answer'], ir123[iid]['model_answer']
    gold = ir42[iid]['gold_answer']
    try:
        if abs(float(a42) - float(a123)) < 0.01 and a42 != a123:
            if ir42[iid]['correct'] != ir123[iid]['correct']:
                format_issues += 1
                if format_issues <= 3:
                    print(f'  Format issue: {iid} gold={gold} s42={a42}({"C" if ir42[iid]["correct"] else "W"}) s123={a123}({"C" if ir123[iid]["correct"] else "W"})')
    except:
        pass
print(f'\nFormat-caused disagreements: {format_issues}')

# Check answer distribution - are s42 answers more "random" looking?
import collections
ans42 = collections.Counter(ir42[iid]['model_answer'] for iid in ir42)
ans123 = collections.Counter(ir123[iid]['model_answer'] for iid in ir123)
print(f'\nUnique answers: s42={len(ans42)} s123={len(ans123)}')
print(f'Top 10 s42: {ans42.most_common(10)}')
print(f'Top 10 s123: {ans123.most_common(10)}')
PYEOF
/root/miniconda3/bin/python /tmp/analyze_gsm8k_2.py
